use crate::error::LexError;

/// One piece of a log line, borrowed from the line itself.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Token<'a> {
    /// The text between `[` and `]`.
    Timestamp(&'a str),
    /// The name in front of `=`.
    Key(&'a str),
    /// A double-quoted value without its quotes, escapes left as written.
    Quoted(&'a str),
    /// An unquoted value; empty for `key=` followed by a space or the end of the line.
    Bare(&'a str),
    /// A run of characters that is neither a timestamp nor part of a pair.
    Word(&'a str),
}

/// What the tokenizer expects next.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum State {
    /// At the start of a token: timestamp, key or word.
    Item,
    /// Just after `key=`: a quoted or bare value.
    Value,
    /// After an error; nothing more is yielded.
    Failed,
}

/// Streams the tokens of one line. After the first error it yields nothing more.
#[derive(Debug, Clone)]
pub struct Tokens<'a> {
    src: &'a str,
    pos: usize,
    state: State,
}

type Step<'a> = Option<Result<Token<'a>, LexError>>;

#[inline(always)]
fn is_sep(c: u8) -> bool {
    c == b' ' || c == b'\t'
}

impl<'a> Tokens<'a> {
    pub fn new(src: &'a str) -> Self {
        Tokens { src, pos: 0, state: State::Item }
    }

    /// Ends the stream with `err`.
    #[cold]
    fn fail(&mut self, err: LexError) -> Step<'a> {
        self.state = State::Failed;
        self.pos = self.src.len();
        Some(Err(err))
    }

    /// Yields `tok`, continuing at `next_pos` in `next_state`.
    #[inline(always)]
    fn emit(&mut self, tok: Token<'a>, next_pos: usize, next_state: State) -> Step<'a> {
        self.state = next_state;
        self.pos = next_pos;
        Some(Ok(tok))
    }

    /// A token that has just ended at `end` must be followed by a separator or the line end.
    #[inline(always)]
    fn check_separator(&self, end: usize) -> Result<(), LexError> {
        match self.src.as_bytes().get(end) {
            Some(&c) if !is_sep(c) => Err(LexError::ExpectedSeparator { pos: end }),
            _ => Ok(()),
        }
    }

    /// Start of a token: skips blanks, then reads a timestamp, key or word.
    fn next_item(&mut self) -> Step<'a> {
        let b = self.src.as_bytes();
        let mut p = self.pos;
        while p < b.len() && is_sep(b[p]) {
            p += 1;
        }
        if p >= b.len() {
            self.pos = p;
            return None;
        }
        match b[p] {
            b'[' => self.timestamp(p),
            b'"' => self.fail(LexError::UnexpectedQuote { pos: p }),
            b'=' => self.fail(LexError::EmptyKey { pos: p }),
            _ => self.key_or_word(p),
        }
    }

    /// `[` at `start`, up to the closing `]`.
    fn timestamp(&mut self, start: usize) -> Step<'a> {
        let b = self.src.as_bytes();
        let body = start + 1;
        let mut i = body;
        loop {
            match b.get(i) {
                None => return self.fail(LexError::UnterminatedTimestamp { pos: start }),
                Some(b']') => break,
                Some(b'[') => return self.fail(LexError::NestedBracket { pos: i }),
                Some(_) => i += 1,
            }
        }
        if let Err(e) = self.check_separator(i + 1) {
            return self.fail(e);
        }
        let tok = Token::Timestamp(&self.src[body..i]);
        self.emit(tok, i + 1, State::Item)
    }

    /// A run up to a blank or `=`: a key if `=` follows, otherwise a word.
    fn key_or_word(&mut self, start: usize) -> Step<'a> {
        let b = self.src.as_bytes();
        let mut i = start;
        while i < b.len() && !is_sep(b[i]) && b[i] != b'=' {
            if b[i] == b'"' {
                return self.fail(LexError::UnexpectedQuote { pos: i });
            }
            i += 1;
        }
        let text = &self.src[start..i];
        if i < b.len() && b[i] == b'=' {
            self.emit(Token::Key(text), i + 1, State::Value)
        } else {
            self.emit(Token::Word(text), i, State::Item)
        }
    }

    /// Right after `key=`: a quoted value, or a bare one (possibly empty).
    fn next_value(&mut self) -> Step<'a> {
        let b = self.src.as_bytes();
        let p = self.pos;
        match b.get(p) {
            None => self.emit(Token::Bare(""), p, State::Item),
